import '../../../app/providers.dart';
import '../../../core/errors/app_error.dart';
import '../../../core/theme/tokens.dart';
import '../../../core/utils/validators.dart';
import '../../../core/widgets/common.dart';
import '../../../core/widgets/surfaces.dart';
import '../../../core/widgets/ui_kit.dart';
import '../../content/data/content_providers.dart';
import '../../content/data/content_source.dart';
import '../../content/domain/site_models.dart';
import '../../shell/app_shell.dart';
import '../data/shop_controllers.dart';

class _CartButton extends ConsumerWidget {
  const _CartButton();
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final n = ref.watch(cartCountProvider);
    return IconButton(
      tooltip: 'Cart',
      onPressed: () => context.push('/cart'),
      icon: Badge(
        isLabelVisible: n > 0,
        label: Text('$n'),
        child: const Icon(Icons.shopping_bag_outlined),
      ),
    );
  }
}

class ShopScreen extends ConsumerStatefulWidget {
  const ShopScreen({super.key});
  @override
  ConsumerState<ShopScreen> createState() => _ShopScreenState();
}

class _ShopScreenState extends ConsumerState<ShopScreen> {
  String _cat = 'All';
  String _q = '';
  int _searchVersion = 0;
  void _clearFilters() => setState(() { _cat = 'All'; _q = ''; _searchVersion++; });
  @override
  Widget build(BuildContext context) {
    final s = ref.watch(siteSettingsProvider);
    final t = Theme.of(context);
    if (!s.sectionEnabled('shop') || s.shopComingSoon) {
      return TabPage(
        title: 'Shop',
        slivers: [
          SliverPadding(
            padding: const EdgeInsets.symmetric(horizontal: HSpace.screen),
            sliver: SliverList.list(
              children: [
                SurfacePanel(
                  radius: HRadius.xl,
                  padding: const EdgeInsets.all(HSpace.xl),
                  child: Column(
                    children: [
                      const IconBadge(
                        icon: Icons.shopping_bag_rounded,
                        color: HColors.special,
                        size: 72,
                      ),
                      const Gap(HSpace.md),
                      Text(
                        'THE PHARMACY EDIT',
                        style: t.textTheme.labelSmall?.copyWith(
                          color: HColors.special,
                          letterSpacing: 1.4,
                        ),
                      ),
                      const Gap(6),
                      Text(
                        'Good things.\nWorth the wait.',
                        style: t.textTheme.headlineMedium,
                        textAlign: TextAlign.center,
                      ),
                      const Gap(HSpace.sm),
                      Text(
                        'Thoughtful essentials for your labs, classes and clinical days.',
                        style: t.textTheme.bodyMedium,
                        textAlign: TextAlign.center,
                      ),
                      const Gap(HSpace.md),
                      const StatusPill(
                        label: 'Shop coming soon',
                        color: HColors.special,
                        icon: Icons.schedule_rounded,
                      ),
                      const Gap(HSpace.md),
                      Wrap(
                        spacing: 8,
                        runSpacing: 8,
                        alignment: WrapAlignment.center,
                        children: const [
                          Chip(label: Text('Lab essentials')),
                          Chip(label: Text('Study companions')),
                          Chip(label: Text('Everyday care')),
                        ],
                      ),
                      const Gap(HSpace.lg),
                      HButton(
                        label: 'Explore notes',
                        onPressed: () => context.go('/study/notes'),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ],
      );
    }
    final catalog = asMap(
      ref.watch(contentProvider('pw_catalog_settings')).valueOrNull?.value,
    );
    final spacing = (num.tryParse('${catalog['gridSpacing']}') ?? 14)
        .clamp(8, 24)
        .toDouble();
    final async = ref.watch(productsProvider);
    final products = async.valueOrNull?.data ?? const <Product>[];
    final cats = [
      'All',
      ...{
        for (final p in products)
          if (p.category.isNotEmpty) p.category,
      },
    ];
    final list =
        products
            .where(
              (p) =>
                  (_cat == 'All' || p.category == _cat) &&
                  (_q.isEmpty ||
                      '${p.name} ${p.category} ${p.shortDesc}'.toLowerCase().contains(_q.toLowerCase())),
            )
            .toList()
          ..sort((a, b) => (b.featured ? 1 : 0) - (a.featured ? 1 : 0));
    return TabPage(
      title: 'Shop',
      subtitle: 'Cash on delivery',
      actions: const [_CartButton()],
      onRefresh: () => refreshContent(ref, ['pw_products', 'pw_delivery']),
      slivers: [
        SliverPadding(
          padding: const EdgeInsets.symmetric(horizontal: HSpace.screen),
          sliver: SliverToBoxAdapter(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Container(padding: const EdgeInsets.all(20), decoration: BoxDecoration(color: const Color(0xff1A3440), borderRadius: BorderRadius.circular(20)), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text('THE PHARMACY EDIT', style: t.textTheme.labelSmall?.copyWith(color: const Color(0xffDDEDEA), letterSpacing: 1.4)),
                  const Gap(8), Text('For your next lab,\nclass and clinical day.', style: t.textTheme.headlineSmall?.copyWith(color: Colors.white)),
                  const Gap(12), Text(async.hasValue ? '${products.length} products in the catalog' : async.hasError ? 'Catalog unavailable. Pull down to retry.' : 'Loading the catalog…', style: t.textTheme.bodyMedium?.copyWith(color: const Color(0xffDDEDEA))),
                ])),
                const Gap(18),
                HSearchField(key: ValueKey('shop-search-$_searchVersion'), initial: _q,
                  hint: 'Search products',
                  onChanged: (v) => setState(() => _q = v),
                ),
                const Gap(HSpace.sm),
                SingleChildScrollView(
                  scrollDirection: Axis.horizontal,
                  child: Row(
                    children: [
                      for (final c in cats)
                        Padding(
                          padding: const EdgeInsets.only(right: 8),
                          child: ChoiceChip(
                            label: Text(c),
                            selected: _cat == c,
                            onSelected: (_) => setState(() => _cat = c),
                          ),
                        ),
                    ],
                  ),
                ),
                const Gap(HSpace.md),
              ],
            ),
          ),
        ),
        if (async.isLoading && products.isEmpty)
          const SliverToBoxAdapter(
            child: Padding(
              padding: EdgeInsets.all(HSpace.screen),
              child: SkeletonList(count: 4, height: 160),
            ),
          )
        else if (async.hasError && products.isEmpty)
          SliverToBoxAdapter(
            child: ErrorState(
              message: 'Couldn\u2019t load products.',
              onRetry: () => refreshContent(ref, ['pw_products']),
            ),
          )
        else if (list.isEmpty)
          SliverToBoxAdapter(child: EmptyState(
            icon: Icons.inventory_2_outlined,
            title: products.isEmpty ? 'No products yet' : 'No matching products',
            message: products.isEmpty ? 'Published products will appear here.' : 'Try a different search or category.',
            action: products.isEmpty ? null : OutlinedButton(onPressed: _clearFilters, child: const Text('Clear filters')),
          ))
        else
          SliverPadding(
            padding: const EdgeInsets.symmetric(horizontal: HSpace.screen),
            sliver: SliverGrid.builder(
              gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                crossAxisCount: MediaQuery.sizeOf(context).width < 360 || MediaQuery.textScalerOf(context).scale(1) > 1.35 ? 1 : MediaQuery.sizeOf(context).width < 600
                    ? (int.tryParse('${catalog['mobileColumns']}') ?? 2).clamp(
                        1,
                        2,
                      )
                    : MediaQuery.sizeOf(context).width < 1000
                    ? (int.tryParse('${catalog['tabletColumns']}') ?? 3).clamp(
                        2,
                        3,
                      )
                    : (int.tryParse('${catalog['desktopColumns']}') ?? 4).clamp(
                        2,
                        4,
                      ),
                mainAxisSpacing: spacing,
                crossAxisSpacing: spacing,
                childAspectRatio: .66,
              ),
              itemCount: list.length,
              itemBuilder: (c, i) => _ProductCard(p: list[i]),
            ),
          ),
      ],
    );
  }
}

class _ProductCard extends ConsumerWidget {
  const _ProductCard({required this.p});
  final Product p;
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final t = Theme.of(context);
    final out = p.availStock <= 0;
    final catalog = asMap(
      ref.watch(contentProvider('pw_catalog_settings')).valueOrNull?.value,
    );
    final radius = (num.tryParse('${catalog['cardRadius']}') ?? 16)
        .clamp(0, 40)
        .toDouble();
    final shadow = switch (catalog['cardShadow']) {
      'none' => 0.0,
      'medium' => 8.0,
      'elevated' => 16.0,
      _ => 4.0,
    };
    return DecoratedBox(
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(radius),
        boxShadow: shadow == 0
            ? null
            : [
                BoxShadow(
                  color: Colors.black.withValues(alpha: .08),
                  blurRadius: shadow,
                  offset: Offset(0, shadow / 3),
                ),
              ],
      ),
      child: HCard(
        radius: radius,
        padding: const EdgeInsets.all(8),
        onTap: () => context.push('/shop/p/${p.id}'),
        semanticLabel: p.name,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Expanded(
              child: NetImage(
                p.image,
                width: double.infinity,
                radius: (radius - 4).clamp(0, 40).toDouble(),
                icon: Icons.medication_rounded,
              ),
            ),
            const Gap(8),
            if (p.category.isNotEmpty)
              Text(
                p.category.toUpperCase(),
                style: t.textTheme.labelSmall,
                maxLines: 1,
              ),
            Text(
              p.name,
              style: t.textTheme.titleSmall,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
            ),
            const Gap(4),
            Wrap(spacing: 6, crossAxisAlignment: WrapCrossAlignment.center,
              children: [
                Text(
                  money(p.price),
                  style: t.textTheme.titleSmall?.copyWith(
                    color: t.colorScheme.primary,
