class _ProductScreenState extends ConsumerState<ProductScreen> {
  final _sel = <String, String>{};
  int _qty = 1;
  int _img = 0;
  @override
  Widget build(BuildContext context) {
    final t = Theme.of(context);
    final p = ref
        .watch(productsProvider)
        .valueOrNull
        ?.data
        .where((x) => x.id == widget.id)
        .firstOrNull;
