                      if (HtmlText.plain(lead.excerpt).isNotEmpty) ...[const Gap(12), Text(HtmlText.plain(lead.excerpt), maxLines: 4, overflow: TextOverflow.ellipsis)],
                    ])),
                  ])), const Gap(16),
                ],
                for (final p in list.where((p) => p != lead))
                  ResourceTile(
                    icon: Icons.article_rounded,
                    color: HColors.info,
                    title: p.title,
                    eyebrow: p.author,
                    subtitle: HtmlText.plain(p.excerpt),
                    onTap: () =>
                        context.push('/blog/${Uri.encodeComponent(p.id)}'),
                  ),
