class BlogPostScreen extends ConsumerWidget {
  const BlogPostScreen({super.key, required this.id});
  final String id;
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final async = ref.watch(blogsProvider);
    final post = async.valueOrNull?.data
        .where((p) => p.id == id || p.slug == id)
        .firstOrNull;
    return TabPage(
      title: post?.title ?? 'Article',
      onRefresh: () => refreshContent(ref, ['pw_blogs']),
      slivers: [
        SliverPadding(
          padding: const EdgeInsets.symmetric(horizontal: HSpace.screen),
          sliver: SliverList.list(
            children: [
              if (!ref.watch(sectionEnabledProvider('blog')))
                const EmptyState(
                  icon: Icons.lock_rounded,
                  title: 'Blog is temporarily unavailable',
                )
              else if (!async.hasValue && async.isLoading)
                const SkeletonList()
              else if (!async.hasValue && async.hasError)
                ErrorState(
                  message: 'Could not load this article.',
                  onRetry: () => refreshContent(ref, ['pw_blogs']),
                )
              else if (post == null)
                const EmptyState(
                  icon: Icons.article_outlined,
                  title: 'Article unavailable',
                  message: 'It may have been moved or unpublished.',
                )
              else ...[
                if (post.coverImage.isNotEmpty)
                  ClipRRect(
                    borderRadius: BorderRadius.circular(HRadius.lg),
                    child: NetImage(post.coverImage, height: 210),
                  ),
                const Gap(HSpace.md),
                Text(
                  post.title,
                  style: Theme.of(context).textTheme.headlineSmall,
                ),
                const Gap(HSpace.sm),
                Text(
                  [
                    post.author,
                    if (post.publishedAt != null)
                      post.publishedAt!
                          .toLocal()
                          .toIso8601String()
                          .split('T')
                          .first,
                  ].where((s) => s.isNotEmpty).join(' · '),
                  style: Theme.of(context).textTheme.bodySmall,
                ),
                const Gap(HSpace.lg),
                HtmlText(post.contentHtml),
              ],
            ],
          ),
        ),
      ],
    );
  }
}

IconData _socialIcon(String platform, String url) {
  final p = '$platform $url'.toLowerCase();
  if (p.contains('instagram')) return FontAwesomeIcons.instagram;
  if (p.contains('facebook')) return FontAwesomeIcons.facebook;
  if (p.contains('whatsapp') || p.contains('wa.me')) {
    return FontAwesomeIcons.whatsapp;
  }
  if (p.contains('youtube') || p.contains('youtu.be')) {
    return FontAwesomeIcons.youtube;
  }
  if (p.contains('linkedin')) return FontAwesomeIcons.linkedin;
  if (p.contains('github')) return FontAwesomeIcons.github;
  if (p.contains('tiktok')) return FontAwesomeIcons.tiktok;
  if (p.contains('telegram') || p.contains('t.me')) {
    return FontAwesomeIcons.telegram;
  }
  if (p.contains('twitter') || p.contains('x.com')) {
    return FontAwesomeIcons.xTwitter;
  }
  return Icons.language_rounded;
}

class AboutScreen extends ConsumerWidget {
  const AboutScreen({super.key});
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final about = ref.watch(aboutProvider);
    final credits = [...ref.watch(creditsProvider)];
    bool isOwner(CreditCard c) => c.name.trim().isNotEmpty && RegExp('owner|founder', caseSensitive: false).hasMatch('${c.role} ${c.designation}');
    credits.sort((a,b) { final rankA = isOwner(a) ? 0 : a.featured ? 1 : 2; final rankB = isOwner(b) ? 0 : b.featured ? 1 : 2; final result = rankA.compareTo(rankB); return result != 0 ? result : a.order.compareTo(b.order); });
    final owner = credits.where(isOwner).firstOrNull;
    final social = ref.watch(socialProvider);
    final data = about.valueOrNull?.data;
    final t = Theme.of(context);
    final scheme = t.colorScheme;
    return TabPage(
      title: 'About',
      subtitle: 'PHARM D WITH HYZEN',
      onRefresh: () =>
          refreshContent(ref, ['pw_about', 'pw_credits', 'pw_social']),
      slivers: [
        SliverPadding(
          padding: const EdgeInsets.symmetric(horizontal: HSpace.screen),
          sliver: SliverList.list(
            children: [
              if (!ref.watch(sectionEnabledProvider('about')))
                const EmptyState(
                  icon: Icons.lock_rounded,
                  title: 'About is temporarily unavailable',
                )
              else ...[
                if (owner != null && owner.photo.isNotEmpty) ...[
                  Center(child: ClipOval(child: SizedBox(width: 110, height: 110, child: NetImage(owner.photo, height: 110)))), const Gap(18),
                ],
                Container(padding: const EdgeInsets.all(24), decoration: BoxDecoration(borderRadius: BorderRadius.circular(16), gradient: const LinearGradient(colors: [Color(0xff1A3440), Color(0xff087F76)])), child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                  Text(owner == null ? 'PHARM D WITH HYZEN' : (owner.role.isNotEmpty ? owner.role : owner.designation).toUpperCase(), textAlign: TextAlign.center, style: t.textTheme.labelSmall?.copyWith(color: const Color(0xffDDEDEA), letterSpacing: 1.2)), const Gap(10),
                  Text(owner?.name ?? 'Built for your next chapter.', textAlign: TextAlign.center, style: t.textTheme.headlineSmall?.copyWith(color: Colors.white)),
                  if (owner != null && owner.designation.isNotEmpty) ...[const Gap(8), Text(owner.designation, textAlign: TextAlign.center, style: t.textTheme.bodyMedium?.copyWith(color: const Color(0xffDDEDEA)))],
                ])), const Gap(18),
                if (owner != null && HtmlText.plain(owner.description).isNotEmpty) HtmlText(owner.description)
                else if (data != null && HtmlText.plain(data.founder).isNotEmpty) HtmlText(data.founder)
                else const Text('Study resources, notes and a practical PDF workspace for Pharm-D students.'),
                if (social.isNotEmpty) ...[const Gap(14), Wrap(spacing: 9, runSpacing: 9, children: [for (final s in social) IconButton.filledTonal(tooltip: s.platform, onPressed: () => openLink(context,s.url), icon: FaIcon(_socialIcon(s.platform,s.url),size:20))])],
                const Gap(22),
                if (!about.hasValue && about.isLoading)
                  const SkeletonList(count: 2),
                if (!about.hasValue && about.hasError)
                  ErrorState(
                    message: 'Could not load our story.',
                    onRetry: () => refreshContent(ref, ['pw_about']),
                  ),
                if (data != null) ...[
                  for (final section in [
                    ('The story', data.about, Icons.auto_stories_outlined),
                    ('Our vision', data.vision, Icons.visibility_outlined),
                    ('Our mission', data.mission, Icons.school_outlined),
                  ])
                    if (HtmlText.plain(section.$2).isNotEmpty) ...[
                      PanelBlock(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              children: [
                                Icon(
                                  section.$3,
                                  color: scheme.primary,
                                  size: 21,
                                ),
                                const SizedBox(width: 10),
                                Expanded(
                                  child: Text(
                                    section.$1,
                                    style: t.textTheme.titleLarge,
