                                ),
                              ],
                            ),
                            const Gap(12),
                            HtmlText(section.$2),
                          ],
                        ),
                      ),
                      const Gap(14),
                    ],
                ],
                if (credits.any((c) => c != owner)) ...[
                  const SectionHeader(title: 'Contributors'),
