class ContactScreen extends ConsumerStatefulWidget {
  const ContactScreen({super.key});
  @override
  ConsumerState<ContactScreen> createState() => _ContactScreenState();
}

class _ContactScreenState extends ConsumerState<ContactScreen> {
  final _form = GlobalKey<FormState>();
  final _name = TextEditingController(),
      _email = TextEditingController(),
      _phone = TextEditingController(),
      _subject = TextEditingController(),
      _body = TextEditingController();
  bool _busy = false;
  @override
  void initState() {
    super.initState();
    final profile = ref.read(profileProvider).valueOrNull;
    final user = ref.read(authStateProvider).valueOrNull;
    _name.text = profile?.fullName ?? user?.displayName ?? '';
    _email.text = user?.email ?? '';
    _phone.text = profile?.mobile ?? '';
  }

  @override
  void dispose() {
    for (final c in [_name, _email, _phone, _subject, _body]) {
      c.dispose();
    }
    super.dispose();
  }

  Future<void> _send() async {
    if (_busy || !_form.currentState!.validate()) return;
    FocusScope.of(context).unfocus();
    setState(() => _busy = true);
    try {
      await submitContactMessage(
        ref.read(firestoreProvider),
        name: _name.text,
        email: _email.text,
        whatsapp: _phone.text,
        subject: _subject.text,
        body: _body.text,
      );
      if (!mounted) return;
      _subject.clear();
      _body.clear();
      showHSnack(context, 'Message sent to the PHARM D WITH HYZEN team');
    } on FriendlyException catch (e) {
      if (mounted) showHSnack(context, e.message, error: true);
    } catch (_) {
      if (mounted) {
        showHSnack(
          context,
          'Message could not be sent. Please try again.',
          error: true,
        );
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final settings = ref.watch(siteSettingsProvider);
    return Scaffold(
      appBar: const HTopBar(title: 'Contact us'),
      body: Form(
        key: _form,
        child: ListView(
          padding: const EdgeInsets.all(HSpace.screen),
          children: [
            const Text(
              'Questions, suggestions or a missing study file? Send the PHARM D WITH HYZEN team a message.',
            ),
            const Gap(HSpace.lg),
            if (settings.email.isNotEmpty)
              ResourceTile(
                icon: Icons.email_outlined,
                color: HColors.primary,
                title: settings.email,
                onTap: () => openLink(context, 'mailto:${settings.email}'),
              ),
            if (settings.whatsapp.isNotEmpty)
              ResourceTile(
                icon: Icons.chat_outlined,
                color: HColors.teal,
                title: 'WhatsApp',
                onTap: () => openLink(context, whatsappUrl(settings.whatsapp)),
              ),
            TextFormField(
              controller: _name,
              decoration: const InputDecoration(labelText: 'Name'),
              validator: (v) =>
                  (v ?? '').trim().isEmpty ? 'Enter your name' : null,
            ),
            const Gap(HSpace.md),
            TextFormField(
              controller: _email,
              keyboardType: TextInputType.emailAddress,
              decoration: const InputDecoration(labelText: 'Email'),
              validator: Validators.email,
            ),
            const Gap(HSpace.md),
            TextFormField(
              controller: _phone,
              keyboardType: TextInputType.phone,
              decoration: const InputDecoration(
                labelText: 'WhatsApp number (optional)',
              ),
            ),
            const Gap(HSpace.md),
            TextFormField(
              controller: _subject,
              maxLength: 120,
              decoration: const InputDecoration(labelText: 'Subject'),
              validator: (v) =>
                  (v ?? '').trim().isEmpty ? 'Enter a subject' : null,
            ),
            const Gap(HSpace.md),
            TextFormField(
              controller: _body,
              minLines: 5,
              maxLines: 10,
              maxLength: 4000,
              decoration: const InputDecoration(labelText: 'Message'),
              validator: (v) => (v ?? '').trim().length < 10
                  ? 'Write at least 10 characters'
                  : null,
            ),
            const Gap(HSpace.lg),
            HButton(
              label: 'Send message',
              icon: Icons.send_rounded,
              loading: _busy,
              onPressed: _busy ? null : _send,
            ),
          ],
        ),
      ),
    );
  }
}
